/* RO-INTEL service worker — Web Push only.
 *
 * Deliberately does NOT cache anything. An offline cache over a live
 * procurement feed is actively harmful: a stale deadline or a withdrawn
 * tender served from cache looks identical to current data, and this
 * product's whole claim is that what you see is what the authority
 * published. Next.js already handles its own asset caching over HTTP.
 *
 * Kept as a plain file in public/ rather than generated by a PWA plugin —
 * it is ~80 lines with one job, and a service worker is the single piece
 * of code that can persist across deploys and break the app for a returning
 * user, so it is worth being able to read all of it at once.
 */

// Take over immediately rather than waiting for every tab to close, so a
// fixed worker actually reaches users on their next visit.
self.addEventListener("install", () => self.skipWaiting());

self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener("push", (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    // A push with a non-JSON body should still surface something rather
    // than being swallowed — Chrome shows a generic "site updated in the
    // background" notice if a push event produces no notification at all.
    payload = { title: "RO-INTEL", body: event.data ? event.data.text() : "" };
  }

  const title = payload.title || "RO-INTEL";
  const options = {
    body: payload.body || "",
    icon: "/icon-192.png",
    badge: "/icon-192.png",
    // Collapses repeat notifications about the same tender into one entry
    // instead of stacking duplicates on the lock screen.
    tag: payload.tag || "ro-intel",
    renotify: false,
    // The dossier URL travels in data, not in the tag: notificationclick
    // has no access to the original payload otherwise.
    data: { url: payload.url || "/cautare-avansata", reason: payload.reason || "criteria" },
    lang: "ro",
    dir: "ltr",
    requireInteraction: false,
    actions: [{ action: "open", title: "Deschide dosarul" }],
  };

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = (event.notification.data && event.notification.data.url) || "/cautare-avansata";

  event.waitUntil(
    (async () => {
      const url = new URL(target, self.location.origin);
      const clientList = await self.clients.matchAll({
        type: "window",
        // Required, or an already-open tab is invisible to this worker and
        // every click opens yet another window.
        includeUncontrolled: true,
      });

      // Prefer focusing an open tab and navigating it, so clicking three
      // alerts does not leave three copies of the app open.
      for (const client of clientList) {
        if (new URL(client.url).origin !== url.origin) continue;
        await client.focus();
        if ("navigate" in client) {
          try {
            await client.navigate(url.href);
          } catch {
            /* A cross-document navigate can be refused; focus alone is
               still better than spawning a duplicate window. */
          }
        }
        return;
      }

      if (self.clients.openWindow) await self.clients.openWindow(url.href);
    })()
  );
});

// Fired when a push service rotates or expires the subscription. Without
// this the device silently stops receiving notifications and neither the
// user nor the server ever learns why.
self.addEventListener("pushsubscriptionchange", (event) => {
  event.waitUntil(
    (async () => {
      const clientList = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      // The page owns the auth token, so re-registration is asked of it
      // rather than attempted here with no credentials.
      for (const client of clientList) client.postMessage({ type: "ro-intel:push-resubscribe" });
    })()
  );
});
